#!/usr/bin/env node
/**
 * Injects iOS entitlements into the generated Xcode entitlements file.
 *
 * `gen/apple/` is fully regenerated by `tauri ios init`, and Tauri exposes no
 * `bundle.iOS.entitlements` config (only macOS has one), so the generated
 * `.entitlements` is always an empty `<dict/>`. This script re-applies the
 * entitlements we need after init — the same pattern as patch-apple-plists.js.
 *
 * Must run AFTER `tauri ios init`. Idempotent: skips keys already present.
 *
 * NOTE: each entitlement here must also be permitted by the provisioning
 * profile (enable the matching capability on the App ID and regenerate the
 * profile), or `codesign` fails with "profile doesn't include the … entitlement".
 *
 * Usage:
 *   node patch-entitlements.js
 */

const fs = require('fs');
const path = require('path');

// Entitlements to ensure are present. Value is the raw plist value XML.
// - com.apple.developer.declared-age-range: required by tauri-plugin-age-signals
//   on iOS 26+ to present the native age-range consent sheet.
const ENTITLEMENTS = {
  'com.apple.developer.declared-age-range': '<true/>',
};

const rootDir = path.resolve(__dirname, '../..');
const entitlementsPath = path.join(
  rootDir,
  'client/src-tauri/gen/apple/bedrock-voice-chat-client_iOS/bedrock-voice-chat-client_iOS.entitlements'
);

if (!fs.existsSync(entitlementsPath)) {
  console.error(`Entitlements file not found (run \`tauri ios init\` first): ${entitlementsPath}`);
  process.exit(1);
}

let content = fs.readFileSync(entitlementsPath, 'utf8');

const additions = [];
for (const [key, value] of Object.entries(ENTITLEMENTS)) {
  if (content.includes(`<key>${key}</key>`)) {
    console.log(`  Already present: ${key}`);
    continue;
  }
  additions.push(`\t<key>${key}</key>\n\t${value}`);
  console.log(`  Adding: ${key} ${value}`);
}

if (additions.length === 0) {
  console.log('Entitlements already up to date.');
  process.exit(0);
}

const block = additions.join('\n');

if (/<dict\s*\/>/.test(content)) {
  // Empty self-closing dict: <dict/>  ->  <dict> … </dict>
  content = content.replace(/<dict\s*\/>/, `<dict>\n${block}\n</dict>`);
} else if (/<\/dict>/.test(content)) {
  // Non-empty dict: insert before the closing tag.
  content = content.replace(/([ \t]*)<\/dict>/, `${block}\n$1</dict>`);
} else {
  console.error('Could not find a <dict> to patch in the entitlements plist.');
  process.exit(1);
}

fs.writeFileSync(entitlementsPath, content);
console.log(`Patched entitlements: ${entitlementsPath}`);
